CREATE TABLE `git_hub_outboxes` (`id` integer PRIMARY KEY AUTOINCREMENT,`ticket_id` text NOT NULL,`kind` text NOT NULL,`payload` text NOT NULL,`idempotency_key` text NOT NULL,`attempts` integer NOT NULL DEFAULT 0,`next_attempt` datetime,`last_error` text,`done_at` datetime);
CREATE TABLE `git_hub_repos` (`id` integer PRIMARY KEY AUTOINCREMENT,`repo_remote` text NOT NULL,`owner` text NOT NULL,`name` text NOT NULL,`enabled` numeric NOT NULL DEFAULT false,`label` text NOT NULL DEFAULT "golem",`last_issue_sync` datetime,`last_polled_at` datetime,`last_manual_sync` datetime,`etag` text,`last_error` text,`graph_build_started_at` datetime,`graph_build_finished_at` datetime,`graph_build_error` text);
