CREATE TABLE `log_entries` (`id` integer PRIMARY KEY AUTOINCREMENT,`ticket_id` text NOT NULL,`sequence_num` integer NOT NULL,`entry_type` text NOT NULL,`from_role` text,`to_role` text,`message` text NOT NULL,`model` text,`backend` text,`created_at` datetime);
CREATE TABLE `sessions` (`id` integer PRIMARY KEY AUTOINCREMENT,`user_id` integer NOT NULL,`token_hash` text NOT NULL,`expires_at` datetime NOT NULL);
CREATE TABLE `shems` (`id` integer PRIMARY KEY AUTOINCREMENT,`name` text NOT NULL,`api_key_hash` text NOT NULL,`repos` text NOT NULL,`last_heartbeat` datetime,`status` text NOT NULL DEFAULT "offline",`current_ticket` text,`backend` text NOT NULL DEFAULT "",`catalog` text NOT NULL DEFAULT "{}");
CREATE TABLE `tickets` (`id` text,`repo_remote` text NOT NULL,`title` text NOT NULL DEFAULT "",`base_branch` text NOT NULL DEFAULT "main",`branch` text NOT NULL,`description` text NOT NULL,`phase` text NOT NULL DEFAULT "unassigned",`assigned_shem` integer,`created_by_user_id` integer,`checkpoint_phase` text,`checkpoint_sha` text,`issue_number` integer,`issue_url` text,`intake_approved` numeric NOT NULL DEFAULT false,`manual_approval` numeric NOT NULL DEFAULT false,`approved_body_hash` text NOT NULL DEFAULT "",`body_hash` text NOT NULL DEFAULT "",`label_phase` text NOT NULL DEFAULT "",`label_seq` integer NOT NULL DEFAULT 0,`pr_body` text NOT NULL DEFAULT "",`pr_number` integer,`pr_url` text,`pr_fix_attempts` integer NOT NULL DEFAULT 0,`pr_last_state` text NOT NULL DEFAULT "",`pr_dispatched_sha` text NOT NULL DEFAULT "",`stopped_from_phase` text NOT NULL DEFAULT "",`models` text NOT NULL DEFAULT "{}",`model_backend` text NOT NULL DEFAULT "",`reaped_from_shem` integer,`reaped_from_phase` text NOT NULL DEFAULT "",`branch_pushed` numeric NOT NULL DEFAULT false,`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`id`));
CREATE TABLE `users` (`id` integer PRIMARY KEY AUTOINCREMENT,`username` text NOT NULL,`password_hash` text NOT NULL,`role` text NOT NULL DEFAULT "developer");
